// compare(a, b) < 0 means a should come out first. Default: smallest number first.
// For a max-heap pass (a, b) => b - a. For pairs pass e.g. (a, b) => a[0] - b[0].
class MinHeap {
  constructor(compare = (a, b) => a - b) {
    this.items = [];
    this.compare = compare;
  }

  size() {
    return this.items.length;
  }

  peek() {
    return this.items[0];
  }

  push(value) {
    this.items.push(value);
    let index = this.items.length - 1;
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.compare(this.items[index], this.items[parent]) >= 0) break;
      [this.items[index], this.items[parent]] = [this.items[parent], this.items[index]];
      index = parent;
    }
  }

  pop() {
    if (this.items.length === 0) return undefined;
    const top = this.items[0];
    const last = this.items.pop();
    if (this.items.length > 0) {
      this.items[0] = last;
      let index = 0;
      const n = this.items.length;
      while (true) {
        const left = 2 * index + 1;
        const right = 2 * index + 2;
        let smallest = index;
        if (left < n && this.compare(this.items[left], this.items[smallest]) < 0) smallest = left;
        if (right < n && this.compare(this.items[right], this.items[smallest]) < 0) smallest = right;
        if (smallest === index) break;
        [this.items[index], this.items[smallest]] = [this.items[smallest], this.items[index]];
        index = smallest;
      }
    }
    return top;
  }
}

tests.code:
const heap = new MinHeap();
[5, 1, 3].forEach((x) => heap.push(x));
assertEqual([heap.pop(), heap.pop(), heap.pop()], [1, 3, 5]);

const heap = new MinHeap();
heap.push(4); heap.push(2); heap.push(9);
assertEqual(heap.peek(), 2);
assertEqual(heap.size(), 3);
heap.push(1);
assertEqual(heap.peek(), 1, 'a newly pushed smallest item must bubble up to the top');

const heap = new MinHeap();
assertEqual(heap.size(), 0);
assertEqual(heap.peek(), undefined);
assertEqual(heap.pop(), undefined);
heap.push(7);
assertEqual(heap.pop(), 7);
assertEqual(heap.pop(), undefined);
assertEqual(heap.size(), 0);

const input = [9, -2, 7, 7, 0, 15, -8, 3, 3, 11, -2, 4];
const heap = new MinHeap();
for (const x of input) heap.push(x);
const out = [];
while (heap.size() > 0) out.push(heap.pop());
assertEqual(out, [-8, -2, -2, 0, 3, 3, 4, 7, 7, 9, 11, 15]);

const heap = new MinHeap();
heap.push(10); heap.push(4); heap.push(8);
assertEqual(heap.pop(), 4);
heap.push(1); heap.push(12); heap.push(6);
assertEqual(heap.pop(), 1);
assertEqual(heap.pop(), 6);
assertEqual(heap.pop(), 8);
assertEqual(heap.size(), 2);

const heap = new MinHeap((a, b) => b - a);
[3, 10, 1, 7].forEach((x) => heap.push(x));
assertEqual([heap.pop(), heap.pop(), heap.pop(), heap.pop()], [10, 7, 3, 1]);

const heap = new MinHeap((a, b) => a[0] - b[0]);
heap.push([3, 'grade essays']); heap.push([1, 'fix login']); heap.push([2, 'email parents']);
assertEqual(heap.pop(), [1, 'fix login']);
assertEqual(heap.peek(), [2, 'email parents']);

const heap = new MinHeap();
[8, 6, 7, 5, 3, 0, 9].forEach((x) => heap.push(x));
heap.pop();
const a = heap.items;
for (let i = 1; i < a.length; i++) {
  assert(a[Math.floor((i - 1) / 2)] <= a[i], 'parent at ' + Math.floor((i - 1) / 2) + ' is bigger than child at ' + i + ': ' + JSON.stringify(a));
}
assertEqual(a.length, 6);
